          "topic on create, description ignored",
          "topic create %s '%s', description create %s topic '%s'" % (a.status, a.get("channel", "topic"), b.status, b.get("channel", "topic")))

    ws2 = workspace(own, "other")
    a = call("POST", C, {"name": "release"}, own["tok"])
